@CrossOrigin
@RestController
@RequestMapping("/OfferQuery")
public class OfferQueryRestController extends BaseSpringRestController {
	
	public OfferQueryRestController( OfferService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Offer using a UUID
     * @param		UUID offerId
     * @return		Offer
     */    
    @GetMapping("/load")
    public Offer load( @RequestParam(required=true) UUID offerId ) {
    	Offer entity = null;

    	try {  
    		entity = service.getOffer( new OfferFetchOneSummary( offerId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Offer using Id " + offerId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Offer business objects
     * @return		Set<Offer>
     */
    @GetMapping("/")
    public List<Offer> loadAll() {                
    	List<Offer> offerList = null;
        
    	try {
            // load the Offer
            offerList = service.getAllOffer();
            
            if ( offerList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Offers" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Offers ", exc );
        	return null;
        }

        return offerList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Offer offer = null;
    protected OfferService service = null;
    private static final Logger LOGGER = Logger.getLogger(OfferQueryRestController.class.getName());
    
}
